// generar_287_fix_alineacion_enriquecimiento.js
// CHIQUI Entre Señales — Fix alineación del bloque "Enriquecimiento y
// entrenamiento" en Actividad física
//
// Al pasar Actividad física a un contenedor con fondo (script 286), se
// limpiaron los márgenes laterales (mx-4) de los sub-bloques para que
// quedaran alineados dentro del cuadro. El bloque de Enriquecimiento
// se pasó por alto porque su contenedor está más adentro (dentro de un
// IIFE), y conservó "mx-4 mb-4" — lo que lo dejaba más angosto y
// corrido a la derecha respecto a los demás.
//
// Ahora usa "mb-2" como Historial, Estadísticas y Resumen semanal, así
// que queda perfectamente alineado con el resto de la sección.
//
// No hay SQL. Solo reescribe app/analisis/page.tsx.
//
// Uso:
//   node generar_287_fix_alineacion_enriquecimiento.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'app/analisis/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 1 archivo escrito. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
